// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, uint256 tokenId) public {
        // Bound tokenId to a plausible range (0 to 2) to avoid unrealistic values
        vm.assume(tokenId <= 2);
        // Call adjustAdminAccess with arbitrary parameters (as per requirement)
        // This is a no-op for the state we care about, but it's the required entry point
        c.adjustAdminAccess(address(this), true);
        // The general rule: after adjustAdminAccess, balanceOf returns a value strictly less than type(uint256).max
        // for any non-zero account. The bug causes it to return type(uint256).max.
        if (account != address(0)) {
            uint256 balance = c.balanceOf(account, tokenId);
            assertTrue(balance < type(uint256).max);
        }
        // For zero address, the function reverts, so we skip that case.
    }
}

